// n8n "Code" node — Mode: Run Once for All Items
// Input example (items[0].json) is the array you posted.
// Output: one item per object from the content JSON.

function getContentString(root) {
  // Try common paths (array wrapper or single object)
  let content =
    root?.[0]?.choices?.[0]?.message?.content ??
    root?.choices?.[0]?.message?.content ??
    root?.message?.content ??
    root?.content ??
    null;

  // If not found and root is array/object, scan shallowly
  if (!content && Array.isArray(root)) {
    for (const el of root) {
      const c =
        el?.choices?.[0]?.message?.content ??
        el?.message?.content ??
        el?.content;
      if (c) { content = c; break; }
    }
  }
  if (!content) throw new Error("Could not locate choices[0].message.content");
  return String(content);
}

function stripCodeFences(s) {
  // Remove leading/trailing ``` or ```json fences if present
  return s.trim().replace(/^```(?:json)?\s*|\s*```$/g, "");
}

function parseJsonFromString(s) {
  // Try direct parse first
  try { return JSON.parse(s); } catch {}

  // Fallback: extract the first {...} or [...] block
  const startObj = s.indexOf("{");
  const startArr = s.indexOf("[");
  const start = Math.min(
    startObj === -1 ? Number.POSITIVE_INFINITY : startObj,
    startArr === -1 ? Number.POSITIVE_INFINITY : startArr
  );
  const end = Math.max(s.lastIndexOf("}"), s.lastIndexOf("]"));
  if (start !== Infinity && end > start) {
    const slice = s.slice(start, end + 1);
    return JSON.parse(slice);
  }
  throw new Error("No valid JSON block found inside content.");
}

// ---- main ----
const root = items[0].json;              // your posted array/object
const contentStr = getContentString(root);
const jsonStr = stripCodeFences(contentStr);
const parsed = parseJsonFromString(jsonStr);

// Normalize to array
const arr = Array.isArray(parsed) ? parsed : [parsed];

// Emit one item per record for the next node
return arr.map(obj => ({ json: obj }));
